for si,group in enumerate(rows):
 for j,row in enumerate(group):
  title,video,intuition,eq,example,exercise,expected,mistake,q,correct,wrong,connection=row
  id=f'{si:02}-{j+1:02}'
  prev=lessons[-1]['id'] if lessons else None
  resourcekeys=(['zero','nn'] if si==0 else ['math','nn'] if si==1 else ['course','micrograd'] if si in [2,3,4] else ['bpe','course'] if si==5 else ['attention','llmc'] if si==6 else ['metalcpp','metal','mlx'] if si==7 else ['mlx','llmc'] if si==8 else ['mlxlm','llama','lora'] if si==9 else ['llama','mlxlm'] if si==10 else ['llmc','mlx'])
  lesson=dict(id=id,stage=si,title=title,minutes=([45,55,60,75,60][j] if si<5 else [75,90,90,75,120][j]),difficulty='Foundation' if si<3 else 'Intermediate' if si<7 else 'Advanced',prerequisites=[prev] if prev else [],concepts=title.lower().replace('&',',').replace(':',',').split(', '),why=connection,objectives=[f'Explain {title.lower()} in your own words.',f'Work through the numerical example and justify each step.',f'Produce the exercise evidence described below.'],explanation=[intuition],equation=eq,example=example,exercise=exercise,guidance='Use double precision for the CPU reference. Keep the calculation separate from input/output. Write down array dimensions before loops, check invalid inputs, and give tests a nonzero exit code on failure.' if si<7 else 'Keep the CPU implementation as an oracle. Pin dependency versions or commits, record configuration and hardware, and report observed results rather than expected performance.',expected=expected,validation=expected,mistake=mistake,question=q,options=[correct,wrong,'There is not enough information to decide'],answer=0,feedback=example+' '+mistake,completion=['Explain the worked example without consulting the answer.','Complete the assignment and record its observed validation results.','Answer the knowledge check, then explicitly mark this lesson complete.'],connection=connection,video=video,resourceKeys=resourcekeys,lab=labnames[si])
  # Vary answer positions so checks cannot be passed with a fixed first-option habit.
  pos=len(lessons)%3
  opts=lesson['options'];opts[0],opts[pos]=opts[pos],opts[0];lesson['answer']=pos
  lessons.append(lesson)
pathlib.Path('src/content/curriculum.json').write_text(json.dumps({'stages':[dict(id=i,title=s[0],description=s[1],outcome=s[2],assignment=s[3],short=s[4]) for i,s in enumerate(stages)],'lessons':lessons},indent=2,ensure_ascii=False))
